import RNA, random, multiprocessing, sys

unit_target='((..(..((....))..(((.(..(.(((...)))..)..)..)))..(..(....)..).(..(....)..).....((....))..)..))'
n=len(unit_target)
complement={'A':'U','U':'A','C':'G','G':'C'}

def cost(seq):
    fc=RNA.fold_compound(seq)
    mfe=fc.mfe()[0]
    return RNA.bp_distance(mfe,unit_target), mfe

def init_seq(seed):
    random.seed(seed)
    seq=['A']*n
    stack=[];pairs=[]
    for i,c in enumerate(unit_target):
        if c=='(': stack.append(i)
        elif c==')': pairs.append((stack.pop(),i))
    for j,i in pairs:
        c=random.choice(['G','C']); seq[j]=c; seq[i]=complement[c]
    for j,i in pairs:
        inside=[(a,b) for a,b in pairs if a>j and b<i]
        if not inside:
            ll=i-j-1
            if ll==4: cap='GAAA'
            elif ll==3: cap='GAA'
            else: cap='A'*ll
            for k,ch in enumerate(cap): seq[j+1+k]=ch
    return seq

def search(seed):
    try:
        random.seed(seed)
        best=init_seq(seed)
        for i in range(n):
            if unit_target[i]=='.' and random.random()<0.4:
                best[i]=random.choice('ACGU')
        cur=''.join(best); c,mfe=cost(cur)
        for it in range(2000):
            if c==0: return (0,''.join(best))
            mm=[i for i in range(n) if mfe[i]!=unit_target[i]]
            if not mm: return (0,''.join(best))
            improved=False
            random.shuffle(mm)
            for i in mm[:6]:
                old=best[i]
                bcl=[]
                for ch in 'ACGU':
                    best[i]=ch
                    nc,nmfe=cost(''.join(best))
                    bcl.append((nc,ch,nmfe))
                best[i]=old
                bcl.sort()
                if bcl[0][0]<c:
                    c=bcl[0][0]; best[i]=bcl[0][1]; mfe=bcl[0][2]; improved=True
            if not improved:
                for _ in range(4):
                    i=random.randrange(n)
                    best[i]=random.choice('ACGU')
                c,mfe=cost(''.join(best))
        return (c,''.join(best))
    except Exception as e:
        return (999,str(e))

if __name__=='__main__':
    with multiprocessing.Pool(48) as p:
        results=p.map(search, range(300))
    results.sort()
    print('best score',results[0][0])
    print('seq',results[0][1])
    if results[0][0]<999:
        fc=RNA.fold_compound(results[0][1])
        print('mfe',fc.mfe()[0])
        print('tgt',unit_target)
    with open('/tmp/unit93.txt','w') as f:
        f.write(results[0][1]+'\n'+str(results[0][0])+'\n')
    sys.stdout.flush()
